export function getEnrichedRecords(records: RawSessionRecord[] = RAW_CSV_RECORDS): EnrichedRecord[] {
  const metaMap = new Map(STUDENT_ROSTER.map(m => [m.student_id, m]));

  return records.map(rec => {
    const meta = metaMap.get(rec.Student_ID) || {
      name: rec.Student_ID,
      code: rec.Student_ID.replace('Student_', 'EXP-50'),
      class: rec.Class,
      gender: 'Female' as const,
      attendanceRate: 90
    };

    let normLevel: 'Excellent' | 'Good' | 'Fair' | 'Needs Support' = 'Fair';
    if (rec.Reading_Score >= 85) {
      normLevel = 'Excellent';
    } else if (rec.Reading_Score >= 70) {
      normLevel = 'Good';
    } else if (rec.Reading_Score >= 55) {
      normLevel = 'Fair';
    } else {
      normLevel = 'Needs Support';
    }

    return {
      ...rec,
      studentName: meta.name,
      displayId: meta.code,
      normalizedLevel: normLevel,
    };
  });
}

export function addStudentToRoster(newMeta: StudentMeta) {
  const existing = STUDENT_ROSTER.find(s => s.student_id === newMeta.student_id);
  if (!existing) {
    STUDENT_ROSTER.push(newMeta);
  }
}
